Can_Tx can_tx_create (Can_Dev can_dev , Can_Tx_Id can_tx_id)
{
  CRITICAL ;

  Can_Tx can_tx = (Can_Tx) os_mem_request (sizeof (struct s_Can_Tx)) ;

  can_tx->can_dev   = can_dev          ;
  can_tx->can_tx_id = can_tx_id        ;
  can_tx->evt_tx    = os_evt_create () ;

  C_ENTER ;
    {
      can_dev->tx[can_tx_id] = can_tx  ;
    }
  C_LEAVE ;

  return can_tx  ;
}

